/** Нержавеющая лента (штрипс х/к) — отдельный источник данных.
 *
 * Собрана из выгрузок двух каталогов (import/lenta-export*.json), а не из
 * pricelist.json: тот правится вручную/парсером, а лента пришла отдельным
 * импортом. Условия отбора клиента: толщина 0,15-0,8 мм, ширина только 200
 * и 400 мм, максимум марок стали (< 0,15 мм — фольга, > 0,8 мм не берём).
 *
 * Цены (руб/кг ×1000 = ₽/т): берём ту, что есть. Приоритет — «zel»; где у
 * zel цены нет, подставляем «sin» для того же SKU. Три марки из «sin»
 * (10Х17Н13М3Т, 12Х18Н9, 12Х18Н9СМР) — со своей ценой sin. «По запросу»
 * (null) остаётся только там, где цены нет ни в одном каталоге.
 *
 * Сгенерировано scripts/_lenta_build.py. Позиций: 612, марок: 20.
 */

export interface LentaSku {
	hub: 'lenta';
	sub: string;
	grade: string;
	roll: string | null;
	alloy: string | null;
	surface: string;
	/** Толщина, мм — строка с запятой (единообразно с pricelist). */
	size: string;
	/** Ширина, мм (200 | 400). */
	width: number;
	/** Толщина, мм — число (для фильтра/карточки). */
	thickness: number;
	/** Ширина как строка — читается PriceTable через поле format ('Ширина'). */
	format: string;
	unit: string;
	price: number | null;
	priceUnit: number | null;
	slug: string;
	dlina: string | null;
	fact: string | null;
	ostatok: number | null;
	gost: string;
	name: string;
}

